// @FIGURE_CODE_BEGIN
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, 900, 450);

// Data and path definitions
const pathPts = [
    {inter: 0.1, slope: 0.15},
    {inter: 0.4, slope: 0.45},
    {inter: 0.6, slope: 0.6},
    {inter: 0.75, slope: 0.65},
    {inter: 0.9, slope: 0.55}
];
const pathColors = ['#c5e1df', '#9acbc7', '#6db4b0', '#419c98', '#2b7a78'];
const dataPoints = [
    {x: 0.1, y: 0.7}, {x: 0.2, y: 0.85}, {x: 0.3, y: 1.05}, {x: 0.4, y: 1.0},
