});

// Evolution Arrow
const arrowMarker = draw.marker(10, 10, function(add) {
  add.path('M 0 0 L 10 5 L 0 10 z').fill('#b0b5b9')
}).ref(8, 5).size(6, 6);

const arrowLabelsX = [0.35, 0.29, 0.23, 0.17, 0.10];
const arrPts = arrowLabelsX.map((x, i) => {
    let p = pathPts[i];
    let y = p.inter + p.slope * x;
    return {
        px: 500 + (x / 2.0) * 350,
        py: 400 - (y / 2.0) * 350
    };
});

// Arrow path constructed via line segments for exact intersection tracking
let arrowPathD = `M ${arrPts[0].px} ${arrPts[0].py}`;
for(let i = 1; i < arrPts.length; i++){
    arrowPathD += ` L ${arrPts[i].px} ${arrPts[i].py}`;
}
panelBGroup.path(arrowPathD)
    .fill('none')
    .stroke({width: 2.5, color: '#b0b5b9', linejoin: 'round'})
    .marker('end', arrowMarker);

// Interactive line
const interactiveLine = panelBGroup.line(0,0,0,0).stroke({width: 4, color: '#ff007f', dasharray: '7,5'});

// Scatter Data
dataPoints.forEach(p => {
    let px = 500 + (p.x / 2.0) * 350;
    let py = 400 - (p.y / 2.0) * 350;
    panelBGroup.circle(13).center(px, py).fill('#d97a53').stroke({width: 1.5, color: '#6b3724'});
});

// Panel B Axes
draw.rect(350, 350).move(500, 50).fill('none').stroke({width: 1.5, color: '#222'});
const xTicksB = [0.0, 0.5, 1.0, 1.5, 2.0];
xTicksB.forEach(val => {
    let tx = 500 + (val / 2.0) * 350;
    let isMajor = val % 1 === 0;
    let tickLen = isMajor ? 6 : 4;
    draw.line(tx, 400, tx, 400 + tickLen).stroke({width: 1.5, color: '#333'});
    if (isMajor) {
        let labelText = (Math.abs(val) < 0.05) ? "0.0" : val.toFixed(1);
        draw.text(labelText).move(tx, 412).font({size: 14, anchor: 'middle', family: 'sans-serif', fill: '#555'});
    }
});
const yTicksB = [0.0, 0.5, 1.0, 1.5, 2.0];
yTicksB.forEach(val => {
    let ty = 400 - (val / 2.0) * 350;
    let isMajor = val % 1 === 0;
    let tickLen = isMajor ? 6 : 4;
    draw.line(500 - tickLen, ty, 500, ty).stroke({width: 1.5, color: '#333'});
    if (isMajor) {
        let labelText = (Math.abs(val) < 0.05) ? "0.0" : val.toFixed(1);
        draw.text(labelText).move(490, ty - 8).font({size: 14, anchor: 'end', family: 'sans-serif', fill: '#555'});
    }
});

// ---------------- Title & Annotations ----------------
draw.text("a)").move(50, 15).font({size: 22, family: 'sans-serif', weight: 'bold'});
draw.text(add => { add.tspan("Loss, "); add.tspan("L[\u03D5]").font({style: 'italic'}); })
    .move(225, 20).font({size: 19, anchor: 'middle', family: 'sans-serif'});
draw.text(add => { add.tspan("Intercept, "); add.tspan("\u03D5\u2080").font({style: 'italic'}); })
    .move(225, 435).font({size: 17, anchor: 'middle', family: 'sans-serif'});
draw.text(add => { add.tspan("Slope, "); add.tspan("\u03D5\u2081").font({style: 'italic'}); })
    .move(20, 225).font({size: 17, anchor: 'middle', family: 'sans-serif'}).transform({rotate: -90, ox: 20, oy: 225});

draw.text("b)").move(500, 15).font({size: 22, family: 'sans-serif', weight: 'bold'});
draw.text(add => { add.tspan("Input, "); add.tspan("x").font({style: 'italic'}); })
    .move(675, 435).font({size: 17, anchor: 'middle', family: 'sans-serif'});
draw.text(add => { add.tspan("Output, "); add.tspan("y").font({style: 'italic'}); })
    .move(465, 225).font({size: 17, anchor: 'middle', family: 'sans-serif'}).transform({rotate: -90, ox: 465, oy: 225});

// Line labels 0-4 positioned precisely along the evolution arrow
const labelOffsets = [
    {dx: 0, dy: 5},    // 0
    {dx: -8, dy: 2},   // 1
    {dx: -10, dy: 0},  // 2
    {dx: -11, dy: -2}, // 3
    {dx: -12, dy: -4}  // 4
];
arrowLabelsX.forEach((x, i) => {
    panelBGroup.text(i.toString())
        .move(arrPts[i].px + labelOffsets[i].dx, arrPts[i].py + labelOffsets[i].dy)
        .font({size: 16, anchor: 'middle', family: 'sans-serif', weight: 'bold', fill: pathColors[i]})
        .attr({'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linecap': 'round', 'stroke-linejoin': 'round'});
});

// Gradient path connecting lines in Panel A
const arrMarkerA = draw.marker(8, 8, function(add) {
  add.path('M 0 0 L 8 4 L 0 8 z').fill('#999')
}).ref(7, 4).size(5, 5);

for (let i = 0; i < pathPts.length - 1; i++) {
    let x1 = 50 + (pathPts[i].inter / 2.0) * 350;
    let y1 = 50 + ((pathPts[i].slope + 1.0) / 2.0) * 350;
    let x2 = 50 + (pathPts[i+1].inter / 2.0) * 350;
    let y2 = 50 + ((pathPts[i+1].slope + 1.0) / 2.0) * 350;
    draw.line(x1, y1, x2, y2).stroke({width: 2.0, color: '#999'}).marker('end', arrMarkerA);
}
pathPts.forEach((p, i) => {
    let x = 50 + (p.inter / 2.0) * 350;
    let y = 50 + ((p.slope + 1.0) / 2.0) * 350;
    draw.circle(13).center(x, y).fill(pathColors[i]).stroke({width: 1.5, color: '#222'});
    draw.text(i.toString()).move(x, y + 9).font({size: 14, anchor: 'middle', family: 'sans-serif', fill: '#fff'});
});

// Interactive Marker
const interactiveMarker = draw.circle(18).center(-100, -100)
    .fill('#ff007f').stroke({width: 2.5, color: '#fff'})
    .css('cursor', 'pointer');
interactiveMarker.on('mouseenter', (e) => showTooltip('Drag to freely explore the parameter space', e)).on('mouseleave', () => hideTooltip());

// ---------------- Interaction Logic ----------------
let currentIntercept = 0.1;
let currentSlope = 0.15;

function updateParams(inter, slope, fromInput = false) {
    currentIntercept = inter;
    currentSlope = slope;

    // Position A Marker (inverted Y)
    let mx = 50 + (inter / 2.0) * 350;
    let my = 50 + ((slope + 1.0) / 2.0) * 350;
    interactiveMarker.cx(mx).cy(my);

    // Position B Line
    let y0 = inter;
    let y2 = inter + slope * 2.0;
    let lx1 = 500;
    let ly1 = 400 - (y0 / 2.0) * 350;
    let lx2 = 850;
    let ly2 = 400 - (y2 / 2.0) * 350;
    interactiveLine.plot(lx1, ly1, lx2, ly2);

    if (!fromInput) {
        document.getElementById('interceptInput').value = inter;
        document.getElementById('interceptVal').value = inter.toFixed(2);
        document.getElementById('slopeInput').value = slope;
        document.getElementById('slopeVal').value = slope.toFixed(2);
    }
}

window.update_intercept = function(v) { updateParams(v, currentSlope, true); };
window.update_slope = function(v) { updateParams(currentIntercept, v, true); };

// Custom dragging logic
let isDragging = false;
const pt = draw.node.createSVGPoint();
function getMouseCoords(e) {
    pt.x = e.clientX;
    pt.y = e.clientY;
    return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}
interactiveMarker.on('mousedown', (e) => {
    isDragging = true;
    e.preventDefault();
});
document.addEventListener('mousemove', (e) => {
    if (!isDragging) return;
    let coords = getMouseCoords(e);
    let x = Math.max(50, Math.min(400, coords.x));
    let y = Math.max(50, Math.min(400, coords.y));
    let intercept = (x - 50) / 350 * 2.0;
    let slope = ((y - 50) / 350 * 2.0) - 1.0; // correctly maps inverted y to slope
    updateParams(intercept, slope, false);
});
document.addEventListener('mouseup', () => { isDragging = false; });

// ---------------- Demo Steps ----------------
const demoSteps = [
    {
        title: "Initial poor fit",
        narration: "At step 0, both the intercept and slope are too low. The resulting line falls far below the data points, placing us in a bright, high-loss region of the parameter space.",
        state: { intercept: 0.1, slope: 0.15 }
    },
    {
        title: "Improving the intercept",
        narration: "Increasing the intercept shifts the line up towards the data cluster. On the loss surface, this horizontal move brings us into the darker valley, significantly reducing the loss.",
        state: { intercept: 0.9, slope: 0.15 }
    },
    {
        title: "Finding the minimum",
        narration: "Increasing the slope rotates the line to closely match the trend of the data. This vertical move on the loss surface lands us at the dark minimum (step 4), representing the line of best fit.",
        state: { intercept: 0.9, slope: 0.55 }
    }
];
let currentStep = 0;
window.setStep = function(index) {
    currentStep = Math.max(0, Math.min(demoSteps.length - 1, index));
    let step = demoSteps[currentStep];

    document.getElementById('demoTitle').innerText = step.title;
    document.getElementById('demoNarration').innerText = step.narration;
    document.getElementById('stepLabel').innerText = `Step ${currentStep + 1} of ${demoSteps.length}`;

    updateParams(step.state.intercept, step.state.slope, false);

    document.getElementById('prevBtn').disabled = (currentStep === 0);
    document.getElementById('nextBtn').disabled = (currentStep === demoSteps.length - 1);
};
window.prevStep = function() { setStep(currentStep - 1); };
window.nextStep = function() { setStep(currentStep + 1); };

// Init
setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The loss landscape maps every possible combination of intercept and slope to a total error, and optimizing a model corresponds to finding the lowest point in this 2D parameter space.
KEY INSIGHT (what students should walk away understanding): Every point on the 2D loss surface represents a unique line in the data space, and gradient descent is simply a path down this surface to the line of best fit.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
