// @FIGURE_CODE_BEGIN
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, 900, 460);

// Data and path definitions
const pathPts = [
    {inter: 0.1, slope: 0.15},
    {inter: 0.4, slope: 0.45},
    {inter: 0.6, slope: 0.6},
    {inter: 0.75, slope: 0.65},
    {inter: 0.9, slope: 0.55}
];
const pathColors = ['#c5e1df', '#9acbc7', '#6db4b0', '#419c98', '#2b7a78'];
const dataPoints = [
    {x: 0.1, y: 0.7}, {x: 0.2, y: 0.85}, {x: 0.3, y: 1.05}, {x: 0.4, y: 1.0},
    {x: 0.8, y: 1.3}, {x: 0.8, y: 1.5}, {x: 1.1, y: 1.2}, {x: 1.3, y: 1.5},
    {x: 1.5, y: 1.4}, {x: 1.65, y: 1.65}, {x: 1.7, y: 1.75}, {x: 1.9, y: 1.5}
];

function interpolateColor(c1, c2, t) {
    let r1 = parseInt(c1.substr(1,2), 16), g1 = parseInt(c1.substr(3,2), 16), b1 = parseInt(c1.substr(5,2), 16);
    let r2 = parseInt(c2.substr(1,2), 16), g2 = parseInt(c2.substr(3,2), 16), b2 = parseInt(c2.substr(5,2), 16);
    let r = Math.round(r1 + (r2 - r1) * t);
    let g = Math.round(g1 + (g2 - g1) * t);
    let b = Math.round(b1 + (b2 - b1) * t);
    // Correct bitwise shift formatting ensuring 6 valid hex characters
    return `#${(1<<24 | r<<16 | g<<8 | b).toString(16).substring(1)}`;
}

// ---------------- Panel A (Loss Surface) ----------------
const clipA = draw.clip();
clipA.add(draw.rect(350, 350).move(50, 50));
const heatmapGroup = draw.group().clipWith(clipA);

// Center the minimum on intercept ~1.35, slope ~0.35 (accounting for inverted y)
const cxA = 50 + (1.35 / 2.0) * 350;
const cyA = 50 + ((0.35 + 1.0) / 2.0) * 350;

const heatmapColors = [
    '#080201', '#1a0602', '#361105', '#571e09', '#7a2c11', 
    '#9c3e1a', '#bc5328', '#d66a3a', '#eb8451', '#f79f6d', 
    '#fdbd8f', '#ffdbb6', '#fff1e3'
];
function getHeatmapColor(t) {
    t = Math.pow(t, 1.35); // Keep the center dark longer
    let cIndex = t * (heatmapColors.length - 1);
    let idx = Math.floor(cIndex);
    if (idx >= heatmapColors.length - 1) return heatmapColors[heatmapColors.length - 1];
    return interpolateColor(heatmapColors[idx], heatmapColors[idx+1], cIndex - idx);
}

// Draw heatmap gradient
const numSteps = 140;
const maxR = 1100;
for (let i = numSteps; i >= 0; i--) {
    let t = i / numSteps;
    let r = t * maxR;
    heatmapGroup.ellipse(r * 2, r * 0.45 * 2)
         .center(cxA, cyA)
         .fill(getHeatmapColor(t))
         .transform({ rotate: -35, ox: cxA, oy: cyA });
}
// Draw contour lines
for (let i = 1; i <= 30; i++) {
    let t = Math.pow(i / 30, 1.2); 
    let r = t * maxR;
    heatmapGroup.ellipse(r * 2, r * 0.45 * 2)
         .center(cxA, cyA)
         .fill('none')
         .stroke({ color: 'rgba(255,255,255,0.22)', width: 1.0 })
         .transform({ rotate: -35, ox: cxA, oy: cyA });
}

// Panel A Axes
draw.rect(350, 350).move(50, 50).fill('none').stroke({width: 1.5, color: '#222'});
for (let i = 0; i <= 10; i++) {
    let val = i * 0.2;
    let tx = 50 + (val / 2.0) * 350;
    let isMajor = (i % 5 === 0);
    let tickLen = isMajor ? 6 : 4;
    draw.line(tx, 400, tx, 400 + tickLen).stroke({width: 1.5, color: '#333'});
