    }
}
for (let i = -5; i <= 5; i++) {
    let val = i * 0.2;
    let ty = 50 + ((val + 1.0) / 2.0) * 350;
    let isMajor = (i % 5 === 0);
    let tickLen = isMajor ? 6 : 4;
    draw.line(50 - tickLen, ty, 50, ty).stroke({width: 1.5, color: '#333'});
    if (isMajor) {
        let labelText = val.toFixed(1);
        draw.text(labelText).move(40, ty - 8).font({size: 14, anchor: 'end', family: 'sans-serif', fill: '#555'});
    }
}

// ---------------- Panel B (Data Space) ----------------
const clipB = draw.clip();
clipB.add(draw.rect(350, 350).move(500, 50));
const panelBGroup = draw.group().clipWith(clipB);

// History Lines
pathPts.forEach((p, i) => {
    let ly1 = 400 - (p.inter / 2.0) * 350;
